123: static void formatTypeTuple(PyObject *t, const char *what, std::ostream &str)
124: {
125:     const Py_ssize_t size = t != nullptr && PyTuple_Check(t) != 0 ? PyTuple_Size(t) : 0;
126:     if (size > 0) {
127:         str << ", " << what << "=[" << size << "]{";
128:         for (Py_ssize_t i = 0; i < size; ++i) {
129:             if (i != 0)
130:                 str << ", ";
