198: // Helper to format a 0-terminated character sequence
199: template <class Char>
200: static void formatCharSequence(const Char *s, std::ostream &str)
201: {
202:     str << '"';
203:     const auto oldFillC = str.fill('0');
204:     str << std::hex;
205:     for (; *s; ++s) {
206:         const unsigned c = *s;
207:         if (c < 127)
208:             str << char(c);
209:         else
210:             str << "0x" << std::right << std::setw(sizeof(Char) * 2) << c << std::left;
211:     }
212:     str << std::dec;
213:     str.fill(oldFillC);
214:     str << '"';
215: }
