217: static void formatPyUnicode(PyObject *obj, std::ostream &str)
218: {
219:     // Note: The below call create the PyCompactUnicodeObject.utf8 representation
220:     str << '"' << PyUnicode_AsUTF8AndSize(obj, nullptr) << '"';
221:     if (!verbose)
222:         return;
223: 
224:     str << " (" << PyUnicode_GetLength(obj) << ')';
225:     const auto kind = _PepUnicode_KIND(obj);
226:     switch (kind) {
227: #if PY_VERSION_HEX < 0x030C0000
228:     case PepUnicode_WCHAR_KIND:
229:         str << " [wchar]";
230:         break;
231: #endif
232:     case PepUnicode_1BYTE_KIND:
233:         str << " [1byte]";
234:         break;
235:     case PepUnicode_2BYTE_KIND:
236:         str << " [2byte]";
237:         break;
238:     case PepUnicode_4BYTE_KIND:
239:         str << " [4byte]";
240:         break;
241:     }
242: 
243:     const bool ascii = _PepUnicode_IS_ASCII(obj);
244:     if (ascii)
245:         str << " [ascii]";
246:     const bool compact = _PepUnicode_IS_COMPACT(obj);
247:     if (compact)
248:         str << " [compact]";
249:     void *data =_PepUnicode_DATA(obj);
250:     str << ", data=";
251:     switch (kind) {
252: #if PY_VERSION_HEX < 0x030C0000
253:     case PepUnicode_WCHAR_KIND:
254:         formatCharSequence(reinterpret_cast<const wchar_t *>(data), str);
255: #endif
256:         break;
257:     case PepUnicode_1BYTE_KIND:
258:         formatCharSequence(reinterpret_cast<const Py_UCS1 *>(data), str);
259:         break;
260:     case PepUnicode_2BYTE_KIND:
261:         formatCharSequence(reinterpret_cast<const Py_UCS2 *>(data), str);
262:         break;
263:     case PepUnicode_4BYTE_KIND:
264:         formatCharSequence(reinterpret_cast<const Py_UCS4 *>(data), str);
265:         break;
266:     }
267: 
268: #ifndef Py_LIMITED_API
269:     const char *utf8 = nullptr;
270:     if (!ascii && compact && kind == PepUnicode_1BYTE_KIND) {
271:         const auto *compactObj = reinterpret_cast<const PyCompactUnicodeObject *>(obj);
272:         if (compactObj->utf8_length)
273:             utf8 = compactObj->utf8;
274:     }
275:     if (utf8) {
276:         str << ", utf8=";
277:         formatCharSequence(reinterpret_cast<const Py_UCS1 *>(utf8), str);
278:     } else {
279:         str << ", no-utf8";
280:     }
281: #endif // !Py_LIMITED_API
282: }
