328: static void formatPyObjectHelper(PyObject *obj, std::ostream &str)
329: {
330:     str << ", ";
331:     if (obj == Py_None) {
332:         str << "None";
333:         return;
334:     }
335:     if (obj == Py_True) {
336:         str << "True";
337:         return;
338:     }
339:     if (obj == Py_False) {
340:         str << "False";
341:         return;
342:     }
343:     const auto refs = Py_REFCNT(obj);
344:     if (refs == UINT_MAX) // _Py_IMMORTAL_REFCNT
345:         str << "immortal, ";
346:     else
347:         str << "refs=" << refs << ", ";
348:     if (PyType_Check(obj)) {
349:         str << "type: ";
350:         formatPyTypeObject(reinterpret_cast<PyTypeObject *>(obj), str, true);
351:         return;
352:     }
353:     formatPyTypeObject(obj->ob_type, str, false);
354:     str << ", ";
355:     if (PyLong_Check(obj)) {
356:         const auto llv = PyLong_AsLongLong(obj);
357:         if (PyErr_Occurred() != PyExc_OverflowError) {
358:             str << llv;
359:         } else {
360:             PyErr_Clear();
361:             str << "0x" << std::hex << PyLong_AsUnsignedLongLong(obj) << std::dec;
362:         }
363:     }
364:     else if (PyFloat_Check(obj))
365:         str << PyFloat_AsDouble(obj);
366:     else if (PyUnicode_Check(obj))
367:         formatPyUnicode(obj, str);
368:     else if (PyFunction_Check(obj) != 0)
369:         formatPyFunction(obj, str);
370:     else if (PyMethod_Check(obj) != 0)
371:         formatPyMethod(obj, str);
372:     else if (PyModule_Check(obj) != 0)
373:         str << "Module \"" << PyModule_GetName(obj) << '"';
374:     else if (PepCode_Check(obj) != 0)
375:         formatPyCodeObject(obj, str);
376:     else if (PySequence_Check(obj))
377:         formatPySequence(obj, str);
378:     else if (PyDict_Check(obj))
379:         formatPyDict(obj, str);
380:     else if (PyTuple_CheckExact(obj))
381:         formatPyTuple(obj, str);
382:     else
383:         str << "<unknown>";
384: }
