497: bool listToArgcArgv(PyObject *argList, int *argcIn, char ***argvIn, const char *defaultAppName)
498: {
499:     *argcIn = 0;
500:     *argvIn = nullptr;
501:     if (!PyList_Check(argList))
502:         return false;
503: 
504:     Shiboken::AutoDecRef args(PySequence_Fast(argList, nullptr));
505:     const Py_ssize_t numArgs = PySequence_Size(argList);
506:     if (numArgs == 0) { // Try to get the script name
507:         auto *argv = new char *[1];
508:         *argvIn = argv;
509:         *argcIn = 1;
510: 
511:         const char *appNameC = nullptr;
512:         Shiboken::AutoDecRef globals(PepEval_GetFrameGlobals());
513:         if (!globals.isNull())  {
514:             if (PyObject *appName = PyDict_GetItem(globals, Shiboken::PyMagicName::file()))
515:                 appNameC = Shiboken::String::toCString(appName);
516:         }
517:         if (appNameC == nullptr)
518:             appNameC = defaultAppName ? defaultAppName : "PySideApplication";
519:         argv[0] = strDup(appNameC);
520:         return true;
521:     }
522: 
523:     auto *argv = new char *[numArgs];
524:     std::fill(argv, argv + numArgs, nullptr);
525: 
526:     for (Py_ssize_t i = 0; i < numArgs; ++i) {
527:         PyObject *item = PyList_GetItem(args.object(), i);
528:         if (Shiboken::String::check(item)) {
529: #ifdef _WIN32
530:             argv[i] = toWindowsConsoleEncoding(item);
531: #else
532:             argv[i] = strDup(Shiboken::String::toCString(item));
533: #endif
534:         } else {
535:             deleteArgv(int(i), argv);
536:             return false;
537:         }
538:     }
539: 
540:     *argcIn = int(numArgs);
541:     *argvIn = argv;
542:     return true;
543: }
