552: int *sequenceToIntArray(PyObject *obj, bool zeroTerminated)
553: {
554:     AutoDecRef seq(PySequence_Fast(obj, "Sequence of ints expected"));
555:     if (seq.isNull())
556:         return nullptr;
557: 
558:     Py_ssize_t size = PySequence_Size(seq.object());
559:     int *array = new int[size + (zeroTerminated ? 1 : 0)];
560: 
561:     for (Py_ssize_t i = 0; i < size; i++) {
562:         Shiboken::AutoDecRef item(PySequence_GetItem(seq.object(), i));
563:         if (!PyLong_Check(item)) {
564:             PyErr_SetString(PyExc_TypeError, "libshiboken: Sequence of ints expected");
565:             delete[] array;
566:             return nullptr;
