35: static void init_phase_1(safe_globals_struc *p)
36: {
37:     do {
38:         /*
39:          * Initializing module signature_bootstrap.
40:          * Since we now have an embedding script, we can do this without any
41:          * Python strings in the C code.
42:          */
43: #if defined(Py_LIMITED_API) || defined(SHIBOKEN_NO_EMBEDDING_PYC)
44:         // We must work for multiple versions or we are cross-building for a different
45:         // Python version interpreter, so use source code.
