134: static int init_phase_2(safe_globals_struc *p, PyMethodDef *methods)
135: {
136:     do {
137:         // The single function to be called, but maybe more to come.
138:         for (PyMethodDef *ml = methods; ml->ml_name != nullptr; ++ml) {
139:             PyObject *v = PyCFunction_NewEx(ml, nullptr, nullptr);
140:             if (v == nullptr
141:                 || PyObject_SetAttrString(p->helper_module, ml->ml_name, v) != 0)
142:                 break;
143:             Py_DECREF(v);
144:         }
145:         // The first entry is __feature_import__, add documentation.
146:         Shiboken::AutoDecRef builtins(PepEval_GetFrameBuiltins());
147:         PyObject *imp_func = PyDict_GetItemString(builtins.object(), "__import__");
148:         builtins.reset(nullptr);
149:         PyObject *imp_doc = PyObject_GetAttrString(imp_func, "__doc__");
