156:         /*********************************************************************
157:          *
158:          * Attention!
159:          * ----------
160:          *
161:          * This is the entry point where everything in folder
162:          * `shibokensupport` becomes initialized. It starts with
163:          * `signature_bootstrap.py` and continues from there to `loader.py`.
164:          *
165:          * The return value of the bootstrap function is the loader module.
166:          */
167:         PyObject *loader = PyObject_CallFunctionObjArgs(bootstrap_func, nullptr);
