180:             break;
181:         p->make_helptext_func = PyObject_GetAttrString(loader, "make_helptext");
182:         if (p->make_helptext_func == nullptr)
183:             break;
184:         p->finish_import_func = PyObject_GetAttrString(loader, "finish_import");
185:         if (p->finish_import_func == nullptr)
186:             break;
187:         p->feature_import_func = PyObject_GetAttrString(loader, "feature_import");
188:         if (p->feature_import_func == nullptr)
