56: // Walk through the first level of non-user-type Sbk base classes relevant for
57: // C++ object allocation. Return true from the predicate to terminate.
58: template <class Predicate>
59: bool walkThroughBases(PyTypeObject *currentType, Predicate predicate)
60: {
61:     PyObject *bases = currentType->tp_bases;
62:     const Py_ssize_t numBases = PyTuple_Size(bases);
63:     bool result = false;
64:     for (Py_ssize_t i = 0; !result && i < numBases; ++i) {
65:         auto *type = reinterpret_cast<PyTypeObject *>(PyTuple_GetItem(bases, i));
66:         if (PyType_IsSubtype(type, SbkObject_TypeF()) != 0) {
67:             result = PepType_SOTP(type)->is_user_type
68:                      ? walkThroughBases(type, predicate) : predicate(type);
69:         }
70:     }
71:     return result;
72: }
