74: int getTypeIndexOnHierarchy(PyTypeObject *baseType, PyTypeObject *desiredType)
75: {
76:     int index = -1;
77:     walkThroughBases(baseType, [&index, desiredType](PyTypeObject *node) {
78:         ++index;
79:         return PyType_IsSubtype(node, desiredType) != 0;
80:     });
81:     return index;
82: }
