322: static PyTypeObject *createObjectType()
323: {
324:     PyType_Slot SbkObject_Type_slots[] = {
325:         {Py_tp_getattro, reinterpret_cast<void *>(SbkObject_GenericGetAttr)},
326:         {Py_tp_setattro, reinterpret_cast<void *>(SbkObject_GenericSetAttr)},
327:         {Py_tp_dealloc, reinterpret_cast<void *>(SbkDeallocWrapperWithPrivateDtor)},
328:         {Py_tp_traverse, reinterpret_cast<void *>(SbkObject_tp_traverse)},
329:         {Py_tp_clear, reinterpret_cast<void *>(SbkObject_tp_clear)},
330:         // unsupported: {Py_tp_weaklistoffset, (void *)offsetof(SbkObject, weakreflist)},
331:         {Py_tp_getset, reinterpret_cast<void *>(SbkObject_tp_getset)},
332:         // unsupported: {Py_tp_dictoffset, (void *)offsetof(SbkObject, ob_dict)},
333:         {0, nullptr}
334:     };
335: 
336:     PyType_Spec SbkObject_Type_spec = {
337: #if SHIBOKEN_MAJOR_VERSION >= 7 // PYSIDE-3336
338:         "2:shiboken6.Shiboken.Object",
339: #else
340:         "1:Shiboken.Object",
341: #endif
342:         sizeof(SbkObject),
343:         0,
344:         Py_TPFLAGS_DEFAULT|Py_TPFLAGS_BASETYPE|Py_TPFLAGS_HAVE_GC,
345:         SbkObject_Type_slots,
346:     };
347: 
348:     // PYSIDE-2230: When creating this type, we cannot easily handle the metaclass.
349:     //              In versions < Python 3.12, the metaclass can only be set
350:     //              indirectly by a base which has that metaclass.
351:     //              But before 3.12 is the minimum version, we cannot use the new
352:     //              function, although we would need this for 3.12 :-D
353:     //              We do a special patching here that is triggered through Py_None.
354:     auto *type = SbkType_FromSpec_BMDWB(&SbkObject_Type_spec,
355:                                         Py_None,     // bases, spectial flag!
356:                                         SbkObjectType_TypeF(),
357:                                         offsetof(SbkObject, ob_dict),
358:                                         offsetof(SbkObject, weakreflist),
359:                                         nullptr);    // bufferprocs
360:     return type;
361: }
