382: static void SbkDeallocWrapperCommon(PyObject *pyObj, bool canDelete)
383: {
384:     auto *sbkObj = reinterpret_cast<SbkObject *>(pyObj);
385:     PyTypeObject *pyType = Py_TYPE(pyObj);
386: 
387:     // Need to decref the type if this is the dealloc func; if type
388:     // is subclassed, that dealloc func will decref (see subtype_dealloc
389:     // in typeobject.c in the python sources)
390:     auto *dealloc = PyType_GetSlot(pyType, Py_tp_dealloc);
391: 
392:     // PYSIDE-939: Additional rule: Also when a subtype is heap allocated,
393:     // then the subtype_dealloc deref will be suppressed, and we need again
394:     // to supply a decref.
395:     const bool needTypeDecref = dealloc == SbkDeallocWrapper
396:         || dealloc == SbkDeallocWrapperWithPrivateDtor
397:         || (pyType->tp_base->tp_flags & Py_TPFLAGS_HEAPTYPE) != 0;
398: 
399: #ifdef __APPLE__
400:     // Just checking once that our assumptions are right.
401:     if (false) {
402:         void *p = PyType_GetSlot(pyType, Py_tp_dealloc);
403:         Dl_info dl_info;
404:         dladdr(p, &dl_info);
405:         fprintf(stderr, "tp_dealloc is %s\n", dl_info.dli_sname);
406:     }
407:     // Gives one of our functions
408:     //  "Sbk_object_dealloc"
409:     //  "SbkDeallocWrapperWithPrivateDtor"
410:     //  "SbkDeallocQAppWrapper"
411:     //  "SbkDeallocWrapper"
412:     // but for typedealloc_test.py we get
413:     //  "subtype_dealloc"
414: #endif
415: 
416:     // Ensure that the GC is no longer tracking this object to avoid a
417:     // possible reentrancy problem.  Since there are multiple steps involved
418:     // in deallocating a SbkObject it is possible for the garbage collector to
419:     // be invoked and it trying to delete this object while it is still in
420:     // progress from the first time around, resulting in a double delete and a
421:     // crash.
422:     PyObject_GC_UnTrack(pyObj);
423: 
424:     // Check that Python is still initialized as sometimes this is called by a static destructor
425:     // after Python interpeter is shutdown.
426:     if (sbkObj->weakreflist && Py_IsInitialized())
427:         PyObject_ClearWeakRefs(pyObj);
428: 
429:     // If I have ownership and is valid delete C++ pointer
430:     auto *sotp = PepType_SOTP(pyType);
431:     canDelete &= sbkObj->d->hasOwnership && sbkObj->d->validCppObject;
432:     if (canDelete) {
433:         if (sotp->delete_in_main_thread && Shiboken::currentThreadId() != Shiboken::mainThreadId()) {
434:             auto &bindingManager = Shiboken::BindingManager::instance();
435:             if (sotp->is_multicpp) {
436:                  const auto entries = Shiboken::getDestructorEntries(sbkObj);
437:                  for (const auto &e : entries)
438:                      bindingManager.addToDeletionInMainThread(e);
439:             } else {
440:                 Shiboken::DestructorEntry e{sotp->cpp_dtor, sbkObj->d->cptr[0]};
441:                 bindingManager.addToDeletionInMainThread(e);
442:             }
443:             Py_AddPendingCall(mainThreadDeletionHandler, nullptr);
444:             canDelete = false;
445:         }
446:     }
447: 
448:     /* Save the current exception, if any. */
449:     Shiboken::Errors::Stash errorStash;
450: 
451:     if (canDelete) {
452:         if (sotp->is_multicpp) {
453:             const auto entries = Shiboken::getDestructorEntries(sbkObj);
454:             Shiboken::Object::deallocData(sbkObj, true);
455:             callDestructor(entries);
456:         } else {
457:             void *cptr = sbkObj->d->cptr[0];
458:             Shiboken::Object::deallocData(sbkObj, true);
459: 
460:             Shiboken::ThreadStateSaver threadSaver;
461:             if (Py_IsInitialized())
462:                 threadSaver.save();
463:             sotp->cpp_dtor(cptr);
464:         }
465:     } else {
466:         Shiboken::Object::deallocData(sbkObj, true);
467:     }
468: 
469:     /* Restore the saved exception. */
470:     errorStash.restore();
471: 
472:     if (needTypeDecref)
473:         Py_DECREF(pyType);
474:     // PYSIDE-939: Handling references correctly.
475:     // This was not needed before Python 3.8 (Python issue 35810)
476:     Py_DECREF(pyType);
477: }
