535: ////////////////////////////////////////////////////////////////////////////
536: //
537: // Support for the qApp macro.
538: //
539: // qApp is a macro in Qt5. In Python, we simulate that a little by a
540: // variable that monitors Q*Application.instance().
541: // This variable is also able to destroy the app by qApp.shutdown().
542: //
543: 
544: PyObject *MakeQAppWrapper(PyTypeObject *type)
545: {
546:     PyObject *&qApp_last = baseWrapperGlobals()->qAppLast;
547: 
548:     // protecting from multiple application instances
549:     if (type != nullptr && qApp_last != Py_None) {
550:         const char *res_name = qApp_last != nullptr
551:             ? PepType_GetNameStr(Py_TYPE(qApp_last)) : "<Unknown>";
552:         const char *type_name = PepType_GetNameStr(type);
553:         PyErr_Format(PyExc_RuntimeError,
554:                      "libshiboken: Please destroy the %s singleton before"
555:                      " creating a new %s instance.", res_name, type_name);
556:         return nullptr;
557:     }
558: 
559:     // monitoring the last application state
560:     PyObject *qApp_curr = type != nullptr ? _Sbk_NewVarObject(type) : Py_None;
561:     Shiboken::AutoDecRef builtins(PepEval_GetFrameBuiltins());
562:     if (PyDict_SetItem(builtins.object(), Shiboken::PyName::qApp(), qApp_curr) < 0)
563:         return nullptr;
564:     builtins.reset(nullptr);
565:     qApp_last = qApp_curr;
566:     // Note: This Py_INCREF would normally be wrong because the qApp
567:     // object already has a reference from PyObject_GC_New. But this is
568:     // exactly the needed reference that keeps qApp alive from alone!
569:     Py_INCREF(qApp_curr);
570:     // PYSIDE-1470: As a side effect, the interactive "_" variable tends to
571:     //              create reference cycles. This is disturbing when trying
572:     //              to remove qApp with del.
573:     // PYSIDE-1758: Since we moved to an explicit qApp.shutdown() call, we
574:     //              no longer initialize "_" with Py_None.
575:     return qApp_curr;
576: }
