578: static PyTypeObject *SbkObjectType_tp_new(PyTypeObject *metatype, PyObject *args, PyObject *kwds)
579: {
580:     // Check if all bases are new style before calling type.tp_new
581:     // Was causing gc assert errors in test_bug704.py when
582:     // this check happened after creating the type object.
583:     // Argument parsing take from type.tp_new code.
584: 
585:     // PYSIDE-595: Also check if all bases allow inheritance.
586:     // Before we changed to heap types, it was sufficient to remove the
587:     // Py_TPFLAGS_BASETYPE flag. That does not work, because PySide does
588:     // not respect this flag itself!
589:     PyObject *name{};
590:     PyObject *pyBases{};
591:     PyObject *dict{};
592:     static const char *kwlist[] = { "name", "bases", "dict", nullptr};
593: 
594:     if (!PyArg_ParseTupleAndKeywords(args, kwds, "OO!O!:sbktype", const_cast<char **>(kwlist),
595:                                      &name,
596:                                      &PyTuple_Type, &pyBases,
597:                                      &PyDict_Type, &dict))
598:         return nullptr;
599: 
600:     for (Py_ssize_t i=0, i_max=PyTuple_Size(pyBases); i < i_max; i++) {
601:         PyObject *baseType = PyTuple_GetItem(pyBases, i);
602:         if (PepExt_Type_GetNewSlot(reinterpret_cast<PyTypeObject *>(baseType)) == SbkDummyNew) {
603:             // PYSIDE-595: A base class does not allow inheritance.
604:             return reinterpret_cast<PyTypeObject *>(SbkDummyNew(metatype, args, kwds));
605:         }
606:     }
607: 
608:     PyTypeObject *newType = PepType_Type_tp_new(metatype, args, kwds);
609: 
610:     if (!newType)
611:         return nullptr;
612: 
613:     SbkObjectTypePrivate *sotp = PepType_SOTP(newType);
614: 
615:     const auto bases = Shiboken::getCppBaseClasses(newType);
616:     if (bases.size() == 1) {
617:         SbkObjectTypePrivate *parentType = PepType_SOTP(bases.front());
618:         sotp->mi_offsets = parentType->mi_offsets;
619:         sotp->mi_init = parentType->mi_init;
620:         sotp->mi_specialcast = parentType->mi_specialcast;
621:         sotp->type_discovery = parentType->type_discovery;
622:         sotp->cpp_dtor = parentType->cpp_dtor;
623:         sotp->is_multicpp = 0;
624:         sotp->converter = parentType->converter;
625:     } else {
626:         sotp->mi_offsets = nullptr;
627:         sotp->mi_init = nullptr;
628:         sotp->mi_specialcast = nullptr;
629:         sotp->type_discovery = nullptr;
630:         sotp->cpp_dtor = nullptr;
631:         sotp->is_multicpp = 1;
632:         sotp->converter = nullptr;
633:     }
634:     if (bases.size() == 1) {
635:         const char *original_name = PepType_SOTP(bases.front())->original_name;
636:         if (original_name == nullptr)
637:             original_name = "object";
638:         sotp->original_name = strdup(original_name);
639:     }
640:     else
641:         sotp->original_name = strdup("object");
642:     sotp->user_data = nullptr;
643:     sotp->d_func = nullptr;
644:     sotp->is_user_type = 1;
645: 
646:     // PYSIDE-1463: Prevent feature switching while in the creation process
647:     auto saveFeature = initSelectableFeature(nullptr);
648:     for (PyTypeObject *base : bases) {
649:         sotp = PepType_SOTP(base);
650:         if (sotp->subtype_init)
651:             sotp->subtype_init(newType, args, kwds);
652:     }
653:     initSelectableFeature(saveFeature);
654:     return newType;
655: }
