657: static PyObject *_setupNew(PyObject *obSelf, PyTypeObject *subtype)
658: {
659:     auto *obSubtype = reinterpret_cast<PyObject *>(subtype);
660:     auto *sbkSubtype = subtype;
661:     auto *self = reinterpret_cast<SbkObject *>(obSelf);
662: 
663:     Py_INCREF(obSubtype);
664:     auto *d = new SbkObjectPrivate;
665: 
666:     auto *sotp = PepType_SOTP(sbkSubtype);
667:     int numBases = ((sotp && sotp->is_multicpp) ?
668:         Shiboken::getNumberOfCppBaseClasses(subtype) : 1);
669:     d->cptr = new void *[numBases];
670:     std::memset(static_cast<void*>(d->cptr), 0, sizeof(void *) *size_t(numBases));
671:     d->hasOwnership = 1;
672:     d->containsCppWrapper = 0;
673:     d->validCppObject = 0;
674:     d->parentInfo = nullptr;
675:     d->referredObjects = nullptr;
676:     d->cppObjectCreated = 0;
677:     d->isQAppSingleton = 0;
678:     self->ob_dict = nullptr;
679:     self->weakreflist = nullptr;
680:     self->d = d;
681:     PyObject_GC_Track(obSelf);
682:     return obSelf;
683: }
