711: // PYSIDE-74: Fallback used in all types now.
712: PyObject *FallbackRichCompare(PyObject *self, PyObject *other, int op)
713: {
714:     // This is a very simple implementation that supplies a simple identity.
715:     static const char * const opstrings[] = {"<", "<=", "==", "!=", ">", ">="};
716:     PyObject *res{};
717: 
718:     switch (op) {
719: 
720:     case Py_EQ:
721:         res = (self == other) ? Py_True : Py_False;
722:         break;
723:     case Py_NE:
724:         res = (self != other) ? Py_True : Py_False;
725:         break;
726:     default:
727:         PyErr_Format(PyExc_TypeError,
728:                      "'%s' not supported between instances of '%.100s' and '%.100s'",
729:                      opstrings[op],
730:                      self->ob_type->tp_name,
731:                      other->ob_type->tp_name);
732:         return nullptr;
733:     }
734:     Py_INCREF(res);
735:     return res;
736: }
