776: // Determine name of a Python override of a virtual method according to features
777: // and populate name cache.
778: static PyObject *overrideMethodName(PyObject *pySelf, const char *methodName,
779:                                     PyObject **nameCache)
780: {
781:     // PYSIDE-1626: Touch the type to initiate switching early.
782:     auto *obType = Py_TYPE(pySelf);
783:     SbkObjectType_UpdateFeature(obType);
784: 
785:     const int flag = currentSelectId(obType);
786:     const int propFlag = isdigit(methodName[0]) ? methodName[0] - '0' : 0;
787:     const bool is_snake = flag & 0x01;
788:     PyObject *pyMethodName = nameCache[is_snake];  // borrowed
789:     if (pyMethodName == nullptr) {
790:         if (propFlag)
791:             methodName += 2; // skip the propFlag and ':'
792:         pyMethodName = Shiboken::String::getSnakeCaseName(methodName, is_snake);
793:         nameCache[is_snake] = pyMethodName;
794:     }
795:     return pyMethodName;
796: }
