798: // The virtual function call
799: PyObject *Sbk_GetPyOverride(const void *voidThis, PyTypeObject *typeObject,
800:                             Shiboken::GilState &gil, const char *funcName,
801:                             PyObject *&resultCache, PyObject **nameCache)
802: {
803:     if (Py_IsInitialized() == 0 || resultCache == Py_None)
804:         return nullptr; // Bail out, execute C++ call (wrappers may outlive Python).
805: 
806:     auto &bindingManager = Shiboken::BindingManager::instance();
807:     SbkObject *wrapper = bindingManager.retrieveWrapper(voidThis, typeObject);
808:     // The refcount can be 0 if the object is dieing and someone called
809:     // a virtual method from the destructor
810:     if (wrapper == nullptr)
811:         return nullptr;
812:     auto *pySelf = reinterpret_cast<PyObject *>(wrapper);
813:     if (Py_REFCNT(pySelf) == 0)
814:         return nullptr;
815: 
816:     gil.acquire();
817:     if (resultCache == Py_None) { // PYSIDE 3246, some other thread may have determined the override
818:         gil.release();
819:         return nullptr;
820:     }
821: 
822:     if (resultCache != nullptr) // recreate the callable from function/self
823:         return PepExt_Type_CallDescrGet(resultCache, pySelf, nullptr);
824: 
825:     PyObject *pyMethodName = overrideMethodName(pySelf, funcName, nameCache);
826:     auto *wrapper_dict = SbkObject_GetDict_NoRef(pySelf);
827: 
828:     // Note: This special case was implemented for duck-punching, which happens
829:     // in the instance dict. It does not work with properties.
830:     // This is not cached to avoid leaking. FIXME PYSIDE 7: Remove (PYSIDE-2916)?
831:     if (PyObject *method = PyDict_GetItem(wrapper_dict, pyMethodName)) {
832:         Py_INCREF(method);
833:         return method;
834:     }
835: 
836:     auto *pyOverride = Shiboken::BindingManager::getOverride(wrapper, pyMethodName);
837:     if (pyOverride == nullptr) {
838:         resultCache = Py_None;
839:         Py_INCREF(resultCache);
840:         gil.release();
841:         return nullptr; // No override, execute C++ call
842:     }
843: 
844:     if (Shiboken::Errors::occurred() != nullptr) {
845:         // Give up.
846:         Py_XDECREF(pyOverride);
847:         resultCache = Py_None;
848:         Py_INCREF(resultCache);
849:         gil.release();
850:         return nullptr; // // Give up.
851:     }
852: 
853:     resultCache = pyOverride;
854:     // recreate the callable from function/self
855:     return PepExt_Type_CallDescrGet(resultCache, pySelf, nullptr);
856: }
