1150: PyTypeObject *
1151: introduceWrapperType(PyObject *enclosingObject,
1152:                      const char *typeName,
1153:                      const char *originalName,
1154:                      PyType_Spec *typeSpec,
1155:                      ObjectDestructor cppObjDtor,
1156:                      PyObject *bases,
1157:                      unsigned wrapperFlags)
1158: {
1159:     assert(PySequence_Size(bases) > 0);
1160:     typeSpec->slots[0].pfunc = PySequence_GetItem(bases, 0);
1161: 
1162:     auto *type = SbkType_FromSpecBasesMeta(typeSpec, bases, SbkObjectType_TypeF());
1163: 
1164:     auto *sotp = PepType_SOTP(type);
1165:     if (wrapperFlags & DeleteInMainThread)
1166:         sotp->delete_in_main_thread = 1;
1167:     sotp->type_behaviour = (wrapperFlags & Value) != 0
1168:                            ? BEHAVIOUR_VALUETYPE : BEHAVIOUR_OBJECTTYPE;
1169: 
1170:     setOriginalName(type, originalName);
1171:     setDestructorFunction(type, cppObjDtor);
1172:     auto *ob_type = reinterpret_cast<PyObject *>(type);
1173: 
1174:     if (wrapperFlags & InternalWrapper) {
1175:         // Type wraps another wrapper class and isn't part of any module.  This is used to extend
1176:         // Qt types with additional functionality, but from within PySide itself.  In order for
1177:         // the re-wrapped class to call the autogenerated __init__ method, is_user_type must be set
1178:         // to 1.  Otherwise the Shiboken::ObjectType::canCallConstructor test will fail.
1179:         // This is currently only used by QtRemoteObjects to create types dynamically.
1180:         sotp->is_user_type = 1;
1181:         return type;
1182:     }
1183: 
1184:     if (wrapperFlags & InnerClass) {
1185:         // PYSIDE-2230: Instead of tp_dict, use the enclosing type.
1186:         //              This stays interface compatible.
1187:         if (PyType_Check(enclosingObject)) {
1188:             AutoDecRef tpDict(PepType_GetDict(reinterpret_cast<PyTypeObject *>(enclosingObject)));
1189:             return PyDict_SetItemString(tpDict, typeName, ob_type) == 0 ? type : nullptr;
1190:         }
1191:         if (PyDict_Check(enclosingObject))
1192:             return PyDict_SetItemString(enclosingObject, typeName, ob_type) == 0 ? type : nullptr;
1193:     }
1194: 
1195:     // PyModule_AddObject steals type's reference.
1196:     Py_INCREF(ob_type);
1197:     if (PepModule_AddType(enclosingObject, type) != 0) {
1198:         std::cerr << "Warning: " << __FUNCTION__ << " returns nullptr for "
1199:             << typeName << '/' << originalName << " due to PyModule_AddObject(enclosingObject="
1200:             << enclosingObject << ", ob_type=" << ob_type << ") failing\n";
1201:         return nullptr;
1202:     }
1203:     return type;
1204: }
