1243: // Find whether base is a direct single line base class of type
1244: // (no multiple inheritance), that is, a C++ pointer cast can safely be done.
1245: static bool isDirectAncestor(PyTypeObject *type, PyTypeObject *base)
1246: {
1247:     if (type == base)
1248:         return true;
1249:     if (PyTuple_Size(type->tp_bases) == 0)
1250:         return false;
1251:     auto *sbkObjectType = SbkObject_TypeF();
1252:     auto *firstBase = reinterpret_cast<PyTypeObject *>(PyTuple_GetItem(type->tp_bases, 0));
1253:     return firstBase != sbkObjectType
1254:            && PyType_IsSubtype(type, sbkObjectType) != 0
1255:            && isDirectAncestor(firstBase, base);
1256: }
