1287: static void setSequenceOwnership(PyObject *pyObj, bool owner)
1288: {
1289: 
1290:     bool has_length = true;
1291: 
1292:     if (!pyObj)
1293:         return;
1294: 
1295:     if (PySequence_Size(pyObj) < 0) {
1296:         PyErr_Clear();
1297:         has_length = false;
1298:     }
1299: 
1300:     if (PySequence_Check(pyObj) && has_length) {
1301:         Py_ssize_t size = PySequence_Size(pyObj);
1302:         if (size > 0) {
1303:             const auto objs = splitPyObject(pyObj);
1304:             if (owner) {
1305:                 for (SbkObject *o : objs)
1306:                     getOwnership(o);
1307:             } else {
1308:                 for (SbkObject *o : objs)
1309:                     releaseOwnership(o);
1310:             }
1311:         }
1312:     } else if (Object::checkType(pyObj)) {
1313:         if (owner)
1314:             getOwnership(reinterpret_cast<SbkObject *>(pyObj));
1315:         else
1316:             releaseOwnership(reinterpret_cast<SbkObject *>(pyObj));
1317:     }
1318: }
