1345:         DestroyQApplication();
1346:         return;
1347:     }
1348:     auto *sotp = PepType_SOTP(Shiboken::pyType(pyObj));
1349:     if (sotp->is_multicpp) {
1350:         callDestructor(getDestructorEntries(pyObj));
1351:     } else {
1352:         Shiboken::ThreadStateSaver threadSaver;
1353:         threadSaver.save();
1354:         sotp->cpp_dtor(pyObj->d->cptr[0]);
