1360: 
1361:     /* invalidate needs to be called before deleting pointer array because
1362:        it needs to delete entries for them from the BindingManager hash table;
1363:        also release wrapper explicitly if object contains C++ wrapper because
1364:        invalidate doesn't */
1365:     invalidate(pyObj);
1366: 
1367:     delete[] priv->cptr;
1368:     priv->cptr = nullptr;
1369:     priv->validCppObject = false;
