1377: void getOwnership(SbkObject *sbkObj)
1378: {
1379:     // skip if already have the ownership
1380:     if (sbkObj->d->hasOwnership)
1381:         return;
1382: 
1383:     // skip if this object has parent
1384:     if (sbkObj->d->parentInfo && sbkObj->d->parentInfo->parent)
1385:         return;
1386: 
1387:     // Get back the ownership
1388:     sbkObj->d->hasOwnership = true;
1389: 
1390:     if (sbkObj->d->containsCppWrapper)
1391:         Py_DECREF(reinterpret_cast<PyObject *>(sbkObj)); // Remove extra ref
1392:     else
