1410:     // remove object ownership
1411:     sbkObj->d->hasOwnership = false;
1412: 
1413:     // If We have control over object life
1414:     if (sbkObj->d->containsCppWrapper)
1415:         Py_INCREF(ob); // keep the python object alive until the wrapper destructor call
1416:     else
1417:         invalidate(sbkObj); // If I do not know when this object will die We need to invalidate this to avoid use after
1418: }
