1440: static void recursive_invalidate(PyObject *pyobj, std::set<SbkObject *> &seen)
1441: {
1442:     const auto objs = splitPyObject(pyobj);
1443:     for (SbkObject *o : objs)
1444:         recursive_invalidate(o, seen);
1445: }
1446: 
1447: static void recursive_invalidate(SbkObject *self, std::set<SbkObject *> &seen)
1448: {
1449:     // Skip if this object not is a valid object or if it's already been seen
1450:     if (!self || reinterpret_cast<PyObject *>(self) == Py_None || seen.find(self) != seen.end())
1451:         return;
1452:     seen.insert(self);
1453: 
1454:     if (!self->d->containsCppWrapper) {
1455:         self->d->validCppObject = false; // Mark object as invalid only if this is not a wrapper class
1456:         BindingManager::instance().releaseWrapper(self);
1457:     }
1458: 
1459:     // If it is a parent invalidate all children.
1460:     if (self->d->parentInfo) {
1461:         // Create a copy because this list can be changed during the process
1462:         ChildrenList copy = self->d->parentInfo->children;
1463: 
1464:         for (SbkObject *child : copy) {
1465:             // invalidate the child
1466:             recursive_invalidate(child, seen);
1467: 
1468:             // if the parent not is a wrapper class, then remove children from him, because We do not know when this object will be destroyed
1469:             if (!self->d->validCppObject)
1470:                 removeParent(child, true, true);
1471:         }
1472:     }
1473: 
1474:     // If has ref to other objects invalidate all
1475:     if (auto *rInfo = self->d->referredObjects) {
1476:         for (const auto &p : *rInfo)
1477:             recursive_invalidate(p.second, seen);
1478:     }
1479: }
1480: 
1481: void makeValid(SbkObject *self)
1482: {
1483:     // Skip if this object not is a valid object
1484:     if (!self || reinterpret_cast<PyObject *>(self) == Py_None || self->d->validCppObject)
1485:         return;
1486: 
1487:     // Mark object as invalid only if this is not a wrapper class
1488:     self->d->validCppObject = true;
1489: 
1490:     // If it is a parent make  all children valid
