112: static bool runProcess(const QString &program, const QStringList &arguments,
113:                        QByteArray *stdOutIn = nullptr, QByteArray *stdErrIn = nullptr)
114: {
115:     QProcess process;
116:     process.start(program, arguments, QProcess::ReadWrite);
117:     if (!process.waitForStarted()) {
118:         qCWarning(lcShiboken).noquote().nospace() << "Unable to start "
119:             << process.program() << ": " << process.errorString();
120:         return false;
121:     }
122:     process.closeWriteChannel();
123:     const bool finished = process.waitForFinished();
124:     const QByteArray stdErr = process.readAllStandardError();
125:     if (stdErrIn)
126:         *stdErrIn = stdErr;
127:     if (stdOutIn)
128:         *stdOutIn = process.readAllStandardOutput();
129: 
130:     if (!finished) {
131:         qCWarning(lcShiboken).noquote().nospace() << process.program() << " timed out: " << stdErr;
132:         process.kill();
133:         return false;
134:     }
135: 
136:     if (process.exitStatus() != QProcess::NormalExit) {
137:         qCWarning(lcShiboken).noquote().nospace() << process.program() << " crashed: " << stdErr;
138:         return false;
139:     }
140: 
141:     if (process.exitCode() != 0) {
142:         qCWarning(lcShiboken).noquote().nospace() <<  process.program() << " exited "
143:             << process.exitCode() << ": " << stdErr;
144:         return false;
145:     }
146: 
147:     return true;
148: }
