152: static void filterHomebrewHeaderPaths(HeaderPaths &headerPaths)
153: {
154:     QByteArray homebrewPrefix = qgetenv("HOMEBREW_OPT");
155: 
156:     // If HOMEBREW_OPT is found we assume that the build is happening
157:     // inside a brew environment, which means we need to filter out
158:     // the -isystem flags added by the brew clang shim. This is needed
159:     // because brew passes the Qt include paths as system include paths
160:     // and because our parser ignores system headers, Qt classes won't
161:     // be found and thus compilation errors will occur.
162:     if (homebrewPrefix.isEmpty())
163:         return;
164: 
165:     ReportHandler::addGeneralMessage("Found HOMEBREW_OPT with value:"_L1
166:                                      + QString::fromUtf8(homebrewPrefix)
167:                                      + "\nAssuming homebrew build environment."_L1);
168: 
169:     HeaderPaths::iterator it = headerPaths.begin();
170:     while (it != headerPaths.end()) {
171:         if (it->path.startsWith(homebrewPrefix)) {
172:             ReportHandler::addGeneralMessage("Filtering out homebrew include path: "_L1
173:                                              + QString::fromUtf8(it->path));
174:             it = headerPaths.erase(it);
175:         } else {
176:             ++it;
177:         }
178:     }
179: }
