181: // Determine g++'s internal include paths from the output of
182: // g++ -E -x c++ - -v </dev/null
183: // Output looks like:
184: // #include <...> search starts here:
185: // /usr/local/include
186: // /System/Library/Frameworks (framework directory)
187: // End of search list.
188: static HeaderPaths gppInternalIncludePaths(const QString &compiler,
189:                                            const QStringList &args)
190: {
191:     HeaderPaths result;
192:     QStringList arguments{u"-E"_s, u"-x"_s, u"c++"_s, u"-"_s, u"-v"_s};
193:     arguments.append(args);
194:     QByteArray stdOut;
195:     QByteArray stdErr;
196:     if (!runProcess(compiler, arguments, &stdOut, &stdErr))
197:         return result;
198:     const QByteArrayList stdErrLines = stdErr.split('\n');
199:     bool isIncludeDir = false;
200: 
201:     for (const QByteArray &line : stdErrLines) {
202:         if (isIncludeDir) {
203:             if (line.startsWith(QByteArrayLiteral("End of search list"))) {
204:                 isIncludeDir = false;
205:             } else {
206:                 HeaderPath headerPath{line.trimmed(), HeaderType::System};
207:                 if (headerPath.path.endsWith(frameworkPath())) {
208:                     headerPath.type = HeaderType::FrameworkSystem;
209:                     headerPath.path.truncate(headerPath.path.size() - frameworkPath().size());
210:                 }
211:                 result.append(headerPath);
212:             }
213:         } else if (line.startsWith("#include <...> search starts here"_ba)) {
214:             isIncludeDir = true;
215:         }
216:     }
217: 
218:     if (_optionsTriplet.platform() == Platform::macOS)
219:         filterHomebrewHeaderPaths(result);
220: 
221:     QString message;
222:     {
223:         QTextStream str(&message);
224:         str << "gppInternalIncludePaths:\n    compiler: " << compiler
225:             << arguments.join(u' ') << '\n';
226:         for (const auto &h : result)
227:             str << "    " << h.path << '\n';
228:         if (ReportHandler::isDebug(ReportHandler::MediumDebug))
229:             str << "    stdOut: " << stdOut << "\n    stdErr: " << stdErr;
230:     }
231:     ReportHandler::addGeneralMessage(message);
232: 
233:     return result;
234: }
