266: static QString queryLlvmConfigDir(const QString &arg)
267: {
268:     static const QString llvmConfig = QStandardPaths::findExecutable(u"llvm-config"_s);
269:     if (llvmConfig.isEmpty())
270:         return {};
271:     QByteArray stdOut;
272:     if (!runProcess(llvmConfig, QStringList{arg}, &stdOut))
273:         return {};
274:     QString path = QFile::decodeName(stdOut.trimmed());
275:     if (!QFileInfo::exists(path)) {
276:         qCWarning(lcShiboken, R"(%s: "%s" as returned by llvm-config "%s" does not exist.)",
277:                   __FUNCTION__, qPrintable(QDir::toNativeSeparators(path)), qPrintable(arg));
278:         return {};
279:     }
280:     return path;
281: }
