283: static QString findClangLibDir()
284: {
285:     for (const char *envVar : {"LLVM_INSTALL_DIR", "CLANG_INSTALL_DIR"}) {
286:         if (qEnvironmentVariableIsSet(envVar)) {
287:             const QString path = QFile::decodeName(qgetenv(envVar)) + u"/lib"_s;
288:             if (QFileInfo::exists(path))
289:                 return path;
290:             qCWarning(lcShiboken, "%s: %s as pointed to by %s does not exist.",
291:                       __FUNCTION__, qPrintable(path), envVar);
292:         }
293:     }
294:     return queryLlvmConfigDir(u"--libdir"_s);
295: }
