297: static QString findClangBuiltInIncludesDir()
298: {
299:     // Find the include directory of the highest version.
300:     const QString clangPathLibDir = findClangLibDir();
301:     if (!clangPathLibDir.isEmpty()) {
302:         QString candidate;
303:         QString clangDirName = clangPathLibDir + u"/clang"_s;
304:         // PYSIDE-2769: llvm-config --libdir may report /usr/lib64 on manylinux_2_28_x86_64
305:         // whereas the includes are under /usr/lib/clang/../include.
306:         if (!QFileInfo::exists(clangDirName) && clangPathLibDir.endsWith("64"_L1)) {
307:             const QString fallback = clangPathLibDir.sliced(0, clangPathLibDir.size() - 2);
308:             clangDirName = fallback + u"/clang"_s;
309:             qCWarning(lcShiboken, "%s: Falling back from %s to %s.",
310:                       __FUNCTION__, qPrintable(clangPathLibDir), qPrintable(fallback));
311:         }
312: 
313:         QVersionNumber lastVersionNumber(1, 0, 0);
314:         QDir clangDir(clangDirName);
315:         const QFileInfoList versionDirs =
316:             clangDir.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot);
317:         if (versionDirs.isEmpty())
318:             qCWarning(lcShiboken, "%s: No subdirectories found in %s.",
319:                       __FUNCTION__, qPrintable(clangDirName));
320:         for (const QFileInfo &fi : versionDirs) {
321:             const QString fileName = fi.fileName();
322:             if (fileName.at(0).isDigit()) {
323:                 const QVersionNumber versionNumber = QVersionNumber::fromString(fileName);
324:                 if (!versionNumber.isNull() && versionNumber > lastVersionNumber) {
325:                     candidate = fi.absoluteFilePath();
326:                     lastVersionNumber = versionNumber;
327:                 }
328:             }
329:         }
330:         if (!candidate.isEmpty())
331:             return candidate + "/include"_L1;
332:     }
333:     return queryLlvmConfigDir(u"--includedir"_s);
334: }
