345: // Return a compiler suitable for determining the internal include paths
346: static QString compilerFromCMake(const QString &defaultCompiler)
347: {
348:     if (!compilerPath().isEmpty())
349:         return compilerPath();
350:     // Exclude macOS since cmakeCompiler returns the full path instead of the
351:     // /usr/bin/clang shim, which results in the default SDK sysroot path
352:     // missing (PYSIDE-1032)
353:     if (_optionsTriplet.platform() == Platform::macOS)
354:         return defaultCompiler;
355:     QString cmakeCompiler = compilerFromCMake();
356:     if (cmakeCompiler.isEmpty())
357:         return defaultCompiler;
358:     QFileInfo fi(cmakeCompiler);
359:     // Should be absolute by default, but a user may specify -DCMAKE_CXX_COMPILER=cl.exe
360:     if (fi.isRelative())
361:         return cmakeCompiler;
362:     if (fi.exists())
363:         return fi.absoluteFilePath();
364:     // The compiler may not exist in case something like icecream or
365:     // a non-standard-path was used on the build machine. Check
366:     // the executable.
367:     cmakeCompiler = QStandardPaths::findExecutable(fi.fileName());
368:     return cmakeCompiler.isEmpty() ? defaultCompiler : cmakeCompiler;
369: }
