387: // Returns clang options needed for emulating the host compiler
388: QByteArrayList emulatedCompilerOptions(LanguageLevel level)
389: {
390:     QByteArrayList result;
391:     HeaderPaths headerPaths;
392:     switch (_optionsTriplet.compiler()) {
393:     case Compiler::Msvc:
394:         result.append("-fms-compatibility-version="_ba + msvcCompatVersion());
395:         if (level < LanguageLevel::Cpp20)
396:             result.append("-fdelayed-template-parsing"_ba);
397:         result.append(QByteArrayLiteral("-Wno-microsoft-enum-value"));
398:         result.append("/Zc:__cplusplus"_ba);
399:         // Fix yvals_core.h:  STL1000: Unexpected compiler version, expected Clang 7 or newer (MSVC2017 update)
400:         result.append(QByteArrayLiteral("-D_ALLOW_COMPILER_AND_STL_VERSION_MISMATCH"));
401:         if (needsClangBuiltinIncludes())
402:             appendClangBuiltinIncludes(&headerPaths);
403:         break;
404:     case Compiler::Clang:
405:         headerPaths.append(gppInternalIncludePaths(compilerFromCMake(u"clang++"_s),
406:                                                    _compilerArguments));
407:         break;
408:     case Compiler::Gpp: {
409:         if (needsClangBuiltinIncludes())
410:             appendClangBuiltinIncludes(&headerPaths);
411: 
412:         // Append the c++ include paths since Clang is unable to find
413:         // <type_traits> etc (g++ 11.3).
414:         const HeaderPaths gppPaths = gppInternalIncludePaths(compilerFromCMake(u"g++"_s),
415:                                                              _compilerArguments);
416:         for (const HeaderPath &h : gppPaths) {
417:             if (h.path.contains("c++") || h.path.contains("sysroot"))
418:                 headerPaths.append(h);
419:         }
420:     }
421:         break;
422:     case Compiler::Unknown:
423:         break;
424:     }
425: 
426:     // For Android cross-compilation, prevent clang from including host system headers that
427:     // conflict with NDK headers.
428:     // This addresses the mbstate_t typedef redefinition error in COIN for RHEL 9.4
429:     if (_optionsTriplet.platform() == Platform::Android
430:         && (_hostTriplet.platform() == Platform::Unix
431:             || _hostTriplet.platform() == Platform::Linux)
432:         && (_optionsTriplet.compiler() == Compiler::Clang
433:             || _optionsTriplet.compiler() == Compiler::Gpp)) {
434:         result.append("-nostdinc");
435:         result.append("-nostdinc++");
436:     }
437: 
438:     std::transform(headerPaths.cbegin(), headerPaths.cend(),
439:                    std::back_inserter(result), HeaderPath::includeOption);
440:     return result;
441: }
