505: void setHeuristicOptions(const QByteArrayList &clangOptions)
506: {
507:     // Figure out compiler type from the binary set
508:     if (!setOptions.testFlag(CompilerOption) && setOptions.testFlag(CompilerPathOption)) {
509:         const QString name = QFileInfo(_compilerPath).baseName().toLower();
510:         if (name.contains("clang"_L1))
511:             _optionsTriplet.setCompiler(Compiler::Clang);
512:         else if (name.contains("cl"_L1))
513:             _optionsTriplet.setCompiler(Compiler::Msvc);
514:         else if (name.contains("gcc"_L1) || name.contains("g++"_L1))
515:             _optionsTriplet.setCompiler(Compiler::Gpp);
516:     }
517: 
518:     // Figure out platform/arch from "--target" triplet
519:     if (!setOptions.testFlag(PlatformOption) && !setOptions.testFlag(ArchitectureOption)) {
520:         auto it = std::find_if(clangOptions.cbegin(), clangOptions.cend(), isTargetOption);
521:         if (it != clangOptions.cend()) {
522:             const QString tripletString = QLatin1StringView(it->sliced(qstrlen(targetOptionC)));
