75:     case QMetaType::QString:
76:         return PyUnicode_FromString(out.toByteArray().constData());
77:     case QMetaType::Short:
78:         return PyLong_FromLong(out.value<short>());
79:     case QMetaType::UShort:
80:         return PyLong_FromUnsignedLong(out.value<unsigned short>());
81:     case QMetaType::Int:
82:         return PyLong_FromLong(out.toInt());
83:     case QMetaType::UInt:
84:         return PyLong_FromUnsignedLong(out.toUInt());
85:     case QMetaType::Long:
86:         return PyLong_FromLong(out.value<long>());
87:     case QMetaType::ULong:
88:         return PyLong_FromUnsignedLong(out.value<unsigned long>());
89:     case QMetaType::LongLong:
90:         return PyLong_FromLongLong(out.toLongLong());
91:     case QMetaType::ULongLong:
92:         return PyLong_FromUnsignedLongLong(out.toULongLong());
93:     case QMetaType::Double:
94:         return PyFloat_FromDouble(out.toDouble());
95:     case QMetaType::Float:
96:     case QMetaType::Float16:
97:         return PyFloat_FromDouble(out.toFloat());
98:     case QMetaType::Bool:
