123: 
124:         const QByteArrayList valuesList = out_ba.split(',');
125:         const Py_ssize_t valuesSize = valuesList.size();
126:         PyObject *list = PyList_New(valuesSize);
127:         for (Py_ssize_t i = 0; i < valuesSize; ++i) {
128:             PyObject *item = PyUnicode_FromString(valuesList.at(i).constData());
129:             PyList_SetItem(list, i, item);
